import {webkit,devices} from 'playwright';
const browser=await webkit.launch({headless:true});
const page=await browser.newPage({...devices['iPhone 13'],userAgent:devices['iPhone 13'].userAgent+' KAKAOTALK'});
page.setDefaultTimeout(18000);
const errors=[],legacy=[];
const member=(id,name,gender,cls,role='member',year=1990,attendance=0)=>({id,name,gender,cls,role,year,age:String(Math.floor((2026-year)/10)*10),type:'member',state:'out',totalGames:12,joinedAt:Date.now()-60000,attendanceMonth:'2026-08',attendanceCount:attendance,attendanceHistory:{'2026-08':attendance}});
const membersA=[member('mgr','배솜다리','여','C','manager',1990,3),member('m1','가나다라','남','C','member',1992,0),member('m2','김회원','여','A','member',1993,2),member('m3','박회원','남','B','organizer',1988,1),...Array.from({length:9},(_,i)=>member('x'+i,'회원'+(i+4),i%2?'여':'남',['A','B','C','D','E'][i%5],'member',1980+i,i%4))];
const membersB=[member('mgrb','배솜다리','여','C','manager',1990,1),member('b1','다른회원','남','D','member',1992,0)];
const state=gid=>({data:{dayKey:'2026-08-31',courtCount:4,courtNames:['1코트','2코트','3코트','4코트'],members:gid==='grp_b'?membersB:membersA,queue:[],pendingGames:[],games:[],history:[],pairCounts:{},attendancePolls:[]},user:{role:'manager',displayName:'배솜다리',memberId:gid==='grp_b'?'mgrb':'mgr',globalAdmin:false,groupId:gid,groupName:gid==='grp_b'?'B모임':'테스트모임'},group:{groupId:gid,name:gid==='grp_b'?'B모임':'테스트모임'},groups:[{groupId:'grp_a',name:'테스트모임'},{groupId:'grp_b',name:'B모임'}]});
await page.addInitScript(()=>{localStorage.setItem('kokmatch_token','qa-roster-token');localStorage.setItem('kokmatch_group_id','grp_a')});
page.on('pageerror',e=>errors.push(e.message));
page.on('request',req=>{try{const p=new URL(req.url()).pathname;if(/^\/app-v/i.test(p)&&p!=='/app-v6.0.js'&&p!=='/app-v6.0.css')legacy.push(p)}catch{}});
await page.route('**/latest-version.json*',r=>r.fulfill({status:200,contentType:'application/json',body:JSON.stringify({version:60,label:'6.0',semanticVersion:'6.0'})}));
await page.route('https://wjelumpbjklfrdjxbesj.supabase.co/functions/v1/**',async route=>{const req=route.request(),u=new URL(req.url()),p=u.pathname;let body={};try{body=req.postData()?JSON.parse(req.postData()):{}}catch{};let out={};if(p.endsWith('/kokmatch-multi-api')){const api=u.searchParams.get('api');if(api==='state')out=state(u.searchParams.get('groupId')||'grp_a');else if(api==='action')out={data:state(body.groupId||'grp_a').data}}else if(p.endsWith('/kokmatch-state-v46')){const g=u.searchParams.get('groupId')||'grp_a';out={...state(g),memberCount:state(g).data.members.length}}else if(p.endsWith('/kokmatch-auth-v38')){if(body.action==='my_memberships')out={memberships:[{groupId:'grp_a',groupName:'테스트모임',memberId:'mgr',role:'manager',roleLabel:'모임관리자'},{groupId:'grp_b',groupName:'B모임',memberId:'mgrb',role:'manager',roleLabel:'모임관리자'}]};else if(body.action==='switch_group')out={success:true,token:'qa-'+body.groupId,groupId:body.groupId,groupName:body.groupId==='grp_b'?'B모임':'테스트모임',memberId:body.groupId==='grp_b'?'mgrb':'mgr',role:'manager',roleLabel:'모임관리자'}}else if(p.endsWith('/kokmatch-profile-v53'))out=u.searchParams.get('full')==='1'?{image:'',fullImage:''}:{profiles:{}};else if(p.endsWith('/kokmatch-v66-api'))out={data:state(body.groupId||'grp_a').data};else if(p.endsWith('/kokmatch-updater'))out={version:60,label:'6.0',autoUpdate:false};else out={data:state(body.groupId||'grp_a').data};await route.fulfill({status:200,contentType:'application/json',body:JSON.stringify(out)})});
await page.goto('http://127.0.0.1:4173/?qa=v6roster',{waitUntil:'domcontentloaded'});
await page.waitForFunction(()=>window.__kokmatchStandalone==='6.0'&&window.__kokmatchInteractionCore==='6.0'&&window.__kokmatchRosterCanonicalV6==='6.0.1');
await page.waitForFunction(()=>document.querySelectorAll('#members .memberCard').length===10);
const diag=await page.evaluate(()=>{const card=id=>document.querySelector(`#members .memberCard[data-member-id22="${id}"]`);const mgr=card('mgr'),m1=card('m1'),name=m1?.querySelector('.memberName45'),main=m1?.querySelector('.memberMainLine45'),att=m1?.querySelector('.memberAttendanceV6'),partner=m1?.querySelector('.rosterPartnerBtnV6'),style=m1?getComputedStyle(m1):null,ns=name?getComputedStyle(name):null;return{mgrRole:mgr?.querySelector('.roleBadge')?.textContent?.trim(),memberRole:m1?.querySelector('.roleBadge')?.textContent?.trim(),main:main?.textContent?.trim(),attendance:att?.textContent?.trim(),partner:partner?.textContent?.trim(),grade:m1?.dataset.gradeV6,bg:style?.backgroundColor,nameOverflow:ns?.overflow,nameEllipsis:ns?.textOverflow,nameText:name?.textContent?.trim(),genericPairs:m1?.querySelectorAll('.pairBtn:not(.partnerSetBtn66),.recordBtn73').length||0}});
console.log('ROSTER DIAG',JSON.stringify(diag));
if(diag.mgrRole!=='모임장')throw new Error('manager badge not renamed: '+diag.mgrRole);
if(diag.memberRole!=='일반')throw new Error('member badge not renamed: '+diag.memberRole);
if(diag.main.includes('총 게임')||diag.main.includes('같이한 경기'))throw new Error('legacy roster info remains: '+diag.main);
if(diag.attendance!=='8월 출석 0회')throw new Error('monthly attendance missing: '+diag.attendance);
if(diag.partner!=='파트너 설정')throw new Error('partner setting missing');
if(diag.genericPairs!==0)throw new Error('legacy pair/record button remains');
if(diag.grade!=='C')throw new Error('grade dataset missing');
if(!diag.bg||diag.bg==='rgb(255, 255, 255)'||diag.bg==='rgba(0, 0, 0, 0)')throw new Error('grade pastel card not applied: '+diag.bg);
if(diag.nameText!=='가나다라'||diag.nameOverflow==='hidden'||diag.nameEllipsis==='ellipsis')throw new Error('four-character name can clip: '+JSON.stringify(diag));
console.log('PASS roster labels/attendance/partner/pastel/name lane');
await page.locator('nav button[data-v="queue"]').click();
await page.waitForFunction(()=>document.getElementById('queue')?.classList.contains('on'));
await page.locator('nav button[data-v="members"]').click();
await page.waitForFunction(()=>document.getElementById('members')?.classList.contains('on')&&document.querySelectorAll('#members .memberCard').length===10);
const reentry=await page.locator('#members .memberCard').count();if(reentry!==10)throw new Error('member roster re-entry incomplete: '+reentry);console.log('PASS member roster re-entry');
await page.locator('#groupBtn').click();await page.waitForSelector('#groupChoiceV6');const choices=await page.locator('#groupChoiceV6 button').count();if(choices!==2)throw new Error('joined groups not fully shown: '+choices);await page.locator('#groupChoiceV6 button').filter({hasText:'B모임'}).click();await page.waitForFunction(()=>window.currentGroupId==='grp_b'&&document.querySelector('#groupBtn')?.textContent.includes('B모임'));console.log('PASS joined-group switch');
if(legacy.length)throw new Error('legacy app asset requested '+JSON.stringify(legacy));if(errors.length)throw new Error('page errors '+JSON.stringify(errors));
console.log('PASS V6 ROSTER FEATURES ALL');await browser.close();
